package java.util.concurrent.atomic; public class AtomicLongArray{private final long[] a;public AtomicLongArray(int n){a=new long[n];}public int length(){return a.length;}public long get(int i){return a[i];}public void set(int i,long v){a[i]=v;}public void lazySet(int i,long v){set(i,v);}public boolean compareAndSet(int i,long old,long v){if(a[i]!=old)return false;a[i]=v;return true;}public long getAndSet(int i,long v){long old=a[i];a[i]=v;return old;}public long getAndAdd(int i,long v){long old=a[i];a[i]+=v;return old;}}